		a.Pattern = "[0-9]+"
		a.MaxLength = CodeLength
		a.Autocomplete = node.InputAttributeAutocompleteOneTimeCode
	})).
		WithMetaLabel(text.NewInfoNodeLabelRecoveryCode()),
	)

